```c
#include <stdio.h>

#define MAXN 10000
#define OFFSET 10000
#define INF (1LL << 60)

int main(void) {
    int N, K, C;
    if (scanf("%d %d %d", &N, &K, &C) != 3) {
        return 0;
    }

    int A[MAXN];
    long long total = 0;
    int frequency[2 * OFFSET + 1] = {0};

    for (int i = 0; i < N; i++) {
        scanf("%d", &A[i]);
        total += A[i];
        frequency[A[i] + OFFSET]++;
    }

    long long covered = 0;

    if (C == 1) {
        int remaining = K;
        for (int value = 0; value <= 2 * OFFSET && remaining > 0; value++) {
            int take = frequency[value] < remaining ? frequency[value] : remaining;
            covered += (long long)take * (value - OFFSET);
            remaining -= take;
        }
    } else {
        long long prefix[MAXN + 1] = {0};
        for (int i = 0; i < N; i++) {
            prefix[i + 1] = prefix[i] + A[i];
        }

        long long dp1[MAXN + 1] = {0};
        long long dp2[MAXN + 1];

        long long *prev = dp1;
        long long *cur = dp2;

        for (int k = 1; k <= K; k++) {
            int first = k * C;
            cur[first - 1] = INF;

            for (int i = first; i <= N; i++) {
                long long best = cur[i - 1];
                long long candidate = prev[i - C] + prefix[i] - prefix[i - C];
                if (candidate < best) {
                    best = candidate;
                }
                cur[i] = best;
            }

            long long *tmp = prev;
            prev = cur;
            cur = tmp;
        }

        covered = prev[N];
    }

    printf("%lld\n", total - covered);
    return 0;
}
```

